// Des: Probe free JSON or iframe URLs behind a thin shell page
// Flo: find candidates > cached winner kind first > robots check (deny on error) > own GET each, capped > validate + word overlap > remember winner per host
// I/O: shell page URL + HTML + Conf + Db (caller) > Got built from the winning response, or null
// ===================================================================
const std = @import("std"); const urln = @import("ut-urlz-norm.zig"); const tmfx = @import("nt-fetc-time.zig"); const vali = @import("sc-reco-vali.zig"); const chrs = @import("pa-char-dete.zig"); const html = @import("pa-html-text.zig"); const find = @import("pa-apiz-find.zig"); const shel = @import("pa-shel-dete.zig"); const trap = @import("pa-trap-dete.zig"); const robo = @import("pa-robo-txtz.zig"); const pipe = @import("ru-page-fetc.zig"); const sqli = @import("st-stor-sqli.zig"); const cfgz = @import("cf-conf-load.zig");
const CF = .{ .agnt = "scra", .wrdz = 24, .wmin = 4, .wmax = 24, .jmin = 20, .jctz = "application/json; charset=utf-8" };
pub fn apizGetz(dbzz: *sqli.Dbzz, aren: std.mem.Allocator, host: []const u8) !?[]const u8 { var stmt = try dbzz.prep("SELECT kind FROM apiz WHERE host=?1;"); defer stmt.fini(); try stmt.bindText(1, host); if (!try stmt.step()) return null; return try aren.dupe(u8, stmt.colzText(0)); }
pub fn apizSetz(dbzz: *sqli.Dbzz, host: []const u8, kind: []const u8, timz: i64) !void { var stmt = try dbzz.prep("INSERT INTO apiz(host,kind,hits,timz) VALUES(?1,?2,1,?3) ON CONFLICT(host) DO UPDATE SET kind=?2,hits=hits+1,timz=?3;"); defer stmt.fini(); try stmt.bindText(1, host); try stmt.bindText(2, kind); try stmt.bindIntz(3, timz); _ = try stmt.step(); }
fn wordOfzz(aren: std.mem.Allocator, page: []const u8) ![]const []const u8 { var list: std.ArrayList([]const u8) = .empty; const titl = (try html.htmlTitl(aren, page)) orelse ""; const text = try html.htmlText(aren, page); for ([_][]const u8{ titl, text }) |srcz| { var indx: usize = 0; while (indx < srcz.len and list.items.len < CF.wrdz) { while (indx < srcz.len and !std.ascii.isAlphanumeric(srcz[indx])) indx += 1; const begz = indx; while (indx < srcz.len and std.ascii.isAlphanumeric(srcz[indx])) indx += 1; if (indx - begz >= CF.wmin and indx - begz <= CF.wmax) try list.append(aren, srcz[begz..indx]); } } return list.toOwnedSlice(aren); }
fn ove2(wor2: []const []const u8, body: []const u8) bool { if (wor2.len == 0) return body.len >= CF.jmin; for (wor2) |word| if (std.ascii.findIgnoreCase(body, word) != null) return true; return false; }
fn roboGetz(gpaz: std.mem.Allocator, aren: std.mem.Allocator, iozz: std.Io, opts: anytype, orig: []const u8) robo.Robo { const urlz = std.fmt.allocPrint(aren, "{s}/robots.txt", .{orig}) catch return .{ .mode = .deny }; var resp = tmfx.fetcTime(gpaz, iozz, urlz, opts, .{}) catch return .{ .mode = .deny }; defer resp.free(gpaz); const mode = robo.roboStat(resp.code); if (mode != .pars) return .{ .mode = mode }; return robo.roboPars(aren, resp.body, CF.agnt) catch .{ .mode = .deny }; }
fn pathOfzz(urlz: []const u8) []const u8 { const sepz = std.mem.find(u8, urlz, "://") orelse return "/"; const rest = urlz[sepz + 3 ..]; const slsh = std.mem.findScalar(u8, rest, '/') orelse return "/"; return rest[slsh..]; }
fn goodJson(aren: std.mem.Allocator, ctyp: []const u8, body: []const u8, wor2: []const []const u8) bool { const trim = std.mem.trim(u8, body, " \t\r\n"); if (trim.len == 0) return false; const jsnl = std.ascii.findIgnoreCase(ctyp, "json") != null or trim[0] == '{' or trim[0] == '['; if (!jsnl) return false; const verd = vali.pageVali(aren, CF.jctz, trim) catch return false; if (verd != .okay) return false; return ove2(wor2, trim); }
fn goodPage(aren: std.mem.Allocator, ctyp: []const u8, body: []const u8, minz: usize, she2: usize, mar2: []const []const u8) bool { if (std.ascii.findIgnoreCase(ctyp, "html") == null) return false; const utf8 = chrs.utf8Conv(aren, chrs.charFind(ctyp, body), body) catch return false; const verd = vali.pageVali(aren, ctyp, utf8) catch return false; if (verd != .okay) return false; if (shel.shelChek(aren, utf8, minz, mar2) catch true) return false; const text = html.htmlText(aren, utf8) catch return false; return text.len > she2; }
pub fn apizProb(gpaz: std.mem.Allocator, aren: std.mem.Allocator, iozz: std.Io, conf: cfgz.Conf, dbzz: *sqli.Dbzz, priv: bool, norm: []const u8, page: []const u8, nowz: i64) !?pipe.Gotz { if (conf.apiz_prob_maxz == 0) return null; const part = try urln.urlzSpli(norm); const can2 = try find.apizFind(aren, norm, page, conf.apiz_path_list); if (can2.len == 0) return null; const opts = try pipe.optsMake(aren, conf, priv); const orig = if (part.dflt) try std.fmt.allocPrint(aren, "{s}://{s}", .{ part.sche, part.host }) else try std.fmt.allocPrint(aren, "{s}://{s}:{d}", .{ part.sche, part.host, part.port }); const rbsz = roboGetz(gpaz, aren, iozz, opts, orig); if (rbsz.mode == .deny) return null; const wor2 = try wordOfzz(aren, page); const she2 = (try html.htmlText(aren, page)).len; const first = try apizGetz(dbzz, aren, part.host); var orde: std.ArrayList(find.Cand) = .empty; if (first) |kind| for (can2) |cand| if (std.mem.eql(u8, cand.kind, kind)) try orde.append(aren, cand); for (can2) |cand| { var dupe = false; for (orde.items) |item| if (std.mem.eql(u8, item.urlz, cand.urlz)) { dupe = true; break; }; if (!dupe) try orde.append(aren, cand); }
var sent: u32 = 0; for (orde.items) |cand| { if (sent >= conf.apiz_prob_maxz) break; if (!robo.roboAllo(rbsz, pathOfzz(cand.urlz)).okay) continue; sent += 1; var resp = tmfx.fetcTime(gpaz, iozz, cand.urlz, opts, .{}) catch continue; defer resp.free(gpaz); if (resp.code < 200 or resp.code >= 300) continue; if (cand.page) { if (!goodPage(aren, resp.ctyp, resp.body, conf.shel_text_minz, she2, conf.shel_mark_list)) continue; try apizSetz(dbzz, part.host, cand.kind, nowz); return .{ .code = 200, .ctyp = try aren.dupe(u8, resp.ctyp), .body = try aren.dupe(u8, resp.body) }; } if (!goodJson(aren, resp.ctyp, resp.body, wor2)) continue; if (conf.judg_fiel_requ.len > 0 and ((trap.poisChek(aren, resp.body, conf.judg_fiel_requ) catch "bad") != null)) continue; try apizSetz(dbzz, part.host, cand.kind, nowz); return .{ .code = 200, .ctyp = CF.jctz, .body = try aren.dupe(u8, resp.body) }; } return null; }
